class TestCodebaseIndexerConcurrency:
    """Tests for concurrent indexing."""
    
    def test_concurrent_indexing(self, indexer):
        """Test that concurrent indexing works correctly."""
        import concurrent.futures
        
        files = ["simple_module.py", "importer.py", "complex_module.py"]
        
        with concurrent.futures.ThreadPoolExecutor(max_workers=3) as executor:
            futures = {executor.submit(indexer.index_file, f): f for f in files}
            results = {}
            for future in concurrent.futures.as_completed(futures):
                f = futures[future]
                try:
                    results[f] = future.result()
                except Exception as e:
                    results[f] = e
        
        assert all(results[f] is not None for f in files)
        assert all(hasattr(results[f], 'signatures') for f in files)
    
    def test_concurrent_index_all(self, indexer):
        """Test that index_all handles concurrency internally."""
        results = indexer.index_all()
        
        assert len(results) > 0
        # All results should be ModuleIndex instances or None
        for module_name, result in results.items():
            if result is not None:
                assert hasattr(result, 'signatures')


